<section class="p-section"><h2>Submit an independent partner course</h2><div class="p-info">These listings are delivered by your institution. They are clearly identified separately from official TCM One programs. Only approved courses are shown publicly.</div><form class="p-form" method="post" action="<?= base_url('/partner/courses') ?>"><?= csrf_field() ?><label>Course name<input name="title" required></label><label>Category<input name="category"></label><label>Duration<input name="duration" placeholder="e.g. 3 months"></label><label>Delivery mode<input name="delivery_mode" placeholder="In person, online, hybrid"></label><label>Original fee (₹)<input type="number" min="0" step="0.01" name="original_fee"></label><label>Current fee (₹)<input type="number" min="0" step="0.01" name="current_fee"></label><label>Certificate provider<input name="certificate_provider"></label><label>Eligibility<input name="eligibility"></label><label class="wide">Description<textarea name="description" rows="4"></textarea></label><div class="wide"><button class="tcm-btn primary">Submit for Review</button></div></form></section>
<section class="p-section"><h2>Submitted courses</h2><?php if(!$rows): ?><div class="p-empty">No partner courses yet.</div><?php else: ?><div class="p-table-wrap"><table class="p-table"><thead><tr><th>Course</th><th>Fee</th><th>Status</th><th>Updated</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= e($r['title']) ?><br><span class="p-muted"><?= e($r['category']??'') ?></span><?php if($r['rejection_reason']): ?><br><span class="p-muted"><?= e($r['rejection_reason']) ?></span><?php endif ?></td><td><?= $r['current_fee']!==null?'₹'.number_format((float)$r['current_fee'],2):'—' ?></td><td><span class="p-pill"><?= e(str_replace('_',' ',$r['review_status'])) ?></span></td><td><?= e(date('d M Y',strtotime($r['updated_at']))) ?></td></tr><?php endforeach ?></tbody></table></div><?php endif ?></section>
